/**
 * The node answers most refusals with an English sentence, which agents and scripts read as it is.
 * A person reads it in their language: each sentence the app can show maps to a catalog message.
 * `from` names the node file that says it, which server-messages.test.ts holds to the sentence.
 */
import { cellProblem } from "../../database/model/cell-problems";
import { t, type MessageKey, type MessageValues } from "../../i18n/i18n";

interface ServerMessage {
  /** The sentence exactly, or a pattern for one with values in it. */
  match: string | RegExp;
  key: MessageKey;
  /** For a pattern: the values its groups carry. */
  values?: (groups: RegExpExecArray) => MessageValues;
  /** The file, relative to services/node/src, that holds the sentence: node source, or a JSON catalog the node renders. */
  from: string;
}

