/** A sentence from the node in the reader's language; one the catalog lacks reads as sent. */
export function presentServerMessage(sentence: string): string {
  for (const entry of SERVER_MESSAGES) {
    if (typeof entry.match === "string") {
      if (entry.match === sentence) return t(entry.key);
      continue;
    }
    const groups = entry.match.exec(sentence);
    if (groups) return t(entry.key, entry.values?.(groups));
  }
  return sentence;
}
